def start_element(name=nil,attrs=[])
      attrs = normalize_attrs(attrs)
      block = @block

      r = { :e => name }
      attrs.each { |pair| r[pair[0]] = pair[1] }

      if @state[:path]
        @state[:path].push r
      end

      case name
      when "entity"
        @state[:path] = [ r ]
        record_device(r)
      when "property"
        return if not @state[:address]
        return if not @state[:props]
        @state[:props] << [ r["type"], r["key"]]
      end
    end

